def _parse_fen(fen):
    parts = fen.split()
    placement = parts[0]
    side = parts[1] if len(parts) > 1 else 'w'
    board = [[None] * 8 for _ in range(8)]
    ranks = placement.split('/')
    for i, rank_str in enumerate(ranks):
        rank = 7 - i
        file = 0
        for ch in rank_str:
            if ch.isdigit():
                file += int(ch)
            else:
                board[rank][file] = ch
                file += 1
    return board, side


def _gen_moves(board, side):
    moves = []
    white = side == 'w'
    for r in range(8):
        for f in range(8):
            p = board[r][f]
            if p is None:
                continue
            is_white = p.isupper()
            if is_white != white:
                continue
            piece = p.upper()
            if piece == 'P':
                direction = 1 if white else -1
                start_rank = 1 if white else 6
                # single push
                nr = r + direction
                if 0 <= nr < 8 and board[nr][f] is None:
                    moves.append((r, f, nr, f))
